package com.essde342.triggerbot.ui.imple; import com.essde342.triggerbot.ui.ISetting; import java.util.function.Consumer; public class NumberSetting implements ISetting{private final String name;private double value,min,max,inc;private final Consumer<Double> cb;public NumberSetting(String n,double v,double a,double b,double i){this(n,v,a,b,i,null);}public NumberSetting(String n,double v,double a,double b,double i,Consumer<Double> c){name=n;value=v;min=a;max=b;inc=i;cb=c;}public String getName(){return name;}public double getDoubleValue(){return value;}public void setValue(double v){value=Math.max(min,Math.min(max,v));if(cb!=null)cb.accept(value);}public void increase(){setValue(value+inc);}public void decrease(){setValue(value-inc);}public double getMin(){return min;}public double getMax(){return max;}public double getIncrement(){return inc;}public Object getValue(){return value;}public void fromString(String s){try{if(s!=null)setValue(Double.parseDouble(s));}catch(Exception ignored){}}}